	}
	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
	if err != nil {
		return nil, fmt.Errorf("resolve git common dir for %s: %w", worktreeRoot, err)
	}
	if err := ensureTestIsolatedStateDir(metadata.CommonDir); err != nil {
		return nil, err
	}
